CREATE TABLE project (
  singleton INTEGER PRIMARY KEY CHECK(singleton = 1),
  project_id TEXT NOT NULL,
  store_incarnation TEXT NOT NULL,
  store_revision INTEGER NOT NULL CHECK(store_revision >= 0)
) STRICT;
CREATE TABLE changes (
  change_id TEXT PRIMARY KEY,
  revision INTEGER NOT NULL CHECK(revision >= 0),
  workflow_contract TEXT NOT NULL CHECK(workflow_contract = 'requirement-first-v1'),
  goal TEXT NOT NULL,
  scope TEXT NOT NULL,
  exclusions TEXT NOT NULL CHECK(json_valid(exclusions)),
  request TEXT NOT NULL CHECK(json_valid(request)),
  authority TEXT NOT NULL CHECK(json_valid(authority)),
  activity_stage TEXT NOT NULL CHECK(activity_stage IN ('requirement-analysis','requirement-review','system-design','architecture-design','design-review','plan','delivery-review','implement','code-review','verify','support')),
  activity_status TEXT NOT NULL CHECK(activity_status IN ('pending','in-progress','blocked','ready','completed','cancelled')),
  activity_owner TEXT NOT NULL CHECK(json_valid(activity_owner)),
  activity_reason TEXT NOT NULL,
  next_action TEXT CHECK(next_action IS NULL OR json_valid(next_action))
) STRICT;
CREATE INDEX changes_by_activity ON changes(activity_stage, activity_status);
CREATE TABLE accounts (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('basis','review','evidence','decision','verification','adoption','work')), id TEXT NOT NULL, PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id) REFERENCES changes(change_id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE bases (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='basis'), id TEXT NOT NULL, basis_kind TEXT NOT NULL CHECK(basis_kind IN ('requirements','design')), decision TEXT NOT NULL CHECK(decision IN ('proposed','accepted')), actor TEXT NOT NULL CHECK(actor IS NULL OR json_valid(actor)), rationale TEXT NOT NULL, PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE reviews (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='review'), id TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose IN ('requirements','design','delivery','code')), scope TEXT NOT NULL CHECK(scope IN ('formal','advisory')), prepared_scope TEXT NOT NULL, prepared_coverage_rationale TEXT NOT NULL, prepared_prepared_by TEXT NOT NULL CHECK(prepared_prepared_by IS NULL OR json_valid(prepared_prepared_by)), assessment_reviewer TEXT CHECK(assessment_reviewer IS NULL OR json_valid(assessment_reviewer)), assessment_contributors TEXT CHECK(assessment_contributors IS NULL OR json_valid(assessment_contributors)), assessment_independence_basis TEXT, assessment_judgment TEXT CHECK(assessment_judgment IN ('approved','changes-requested','blocked','inconclusive')), assessment_summary TEXT, assessment_rationale TEXT CHECK(assessment_rationale IS NULL OR json_valid(assessment_rationale)), assessment_limitations TEXT CHECK(assessment_limitations IS NULL OR json_valid(assessment_limitations)), applicability_value TEXT NOT NULL CHECK(applicability_value IN ('current','needs-reassessment','not-applicable')), applicability_actor TEXT NOT NULL CHECK(applicability_actor IS NULL OR json_valid(applicability_actor)), applicability_rationale TEXT NOT NULL, applicability_observation TEXT NOT NULL CHECK(applicability_observation IS NULL OR json_valid(applicability_observation)), PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE evidence (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='evidence'), id TEXT NOT NULL, actor TEXT NOT NULL CHECK(actor IS NULL OR json_valid(actor)), reported_at TEXT NOT NULL, procedure TEXT NOT NULL, scope TEXT NOT NULL, observation TEXT NOT NULL CHECK(observation IS NULL OR json_valid(observation)), result TEXT NOT NULL CHECK(result IN ('passed','failed','inconclusive')), summary TEXT NOT NULL, limitations TEXT NOT NULL CHECK(limitations IS NULL OR json_valid(limitations)), PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE decisions (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='decision'), id TEXT NOT NULL, actor TEXT NOT NULL CHECK(actor IS NULL OR json_valid(actor)), scope TEXT NOT NULL, decision TEXT NOT NULL, rationale TEXT NOT NULL, PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE verifications (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='verification'), id TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('scoped','final')), verifier TEXT NOT NULL CHECK(verifier IS NULL OR json_valid(verifier)), observation TEXT NOT NULL CHECK(observation IS NULL OR json_valid(observation)), outcome TEXT NOT NULL CHECK(outcome IN ('success','failed','inconclusive')), summary TEXT NOT NULL, rationale TEXT NOT NULL CHECK(rationale IS NULL OR json_valid(rationale)), limitations TEXT NOT NULL CHECK(limitations IS NULL OR json_valid(limitations)), support_state TEXT NOT NULL CHECK(support_state IN ('current','needs-reassessment')), PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE adoptions (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='adoption'), id TEXT NOT NULL, actor TEXT NOT NULL CHECK(actor IS NULL OR json_valid(actor)), source_contract TEXT NOT NULL, target_workflow TEXT NOT NULL, source_basis TEXT NOT NULL, compatibility TEXT NOT NULL, disposition TEXT NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('prepared','activated','unavailable')), rationale TEXT NOT NULL, PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE work (change_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='work'), id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','in-progress','blocked','ready','completed','cancelled')), owner TEXT NOT NULL CHECK(owner IS NULL OR json_valid(owner)), scope TEXT NOT NULL, locations TEXT NOT NULL CHECK(locations IS NULL OR json_valid(locations)), remaining TEXT, completion_reason TEXT, PRIMARY KEY(change_id,kind,id), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE blockers (change_id TEXT NOT NULL, id TEXT NOT NULL, reporter TEXT NOT NULL CHECK(json_valid(reporter)), owner TEXT NOT NULL CHECK(json_valid(owner)), scope TEXT NOT NULL, description TEXT NOT NULL, required_outcome TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('open','resolved','withdrawn','deferred')), disposition TEXT CHECK(disposition IS NULL OR json_valid(disposition)), CHECK((state='open' AND disposition IS NULL) OR (state!='open' AND disposition IS NOT NULL)), PRIMARY KEY(change_id,id), FOREIGN KEY (change_id) REFERENCES changes(change_id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE findings (change_id TEXT NOT NULL, review_id TEXT NOT NULL, review_kind TEXT NOT NULL DEFAULT 'review' CHECK(review_kind='review'), id TEXT NOT NULL, reporter TEXT NOT NULL CHECK(json_valid(reporter)), owner TEXT NOT NULL CHECK(json_valid(owner)), scope TEXT NOT NULL, description TEXT NOT NULL, required_outcome TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('open','resolved','withdrawn','deferred')), disposition TEXT CHECK(disposition IS NULL OR json_valid(disposition)), CHECK((state='open' AND disposition IS NULL) OR (state!='open' AND disposition IS NOT NULL)), PRIMARY KEY(change_id,review_id,id), FOREIGN KEY (change_id,review_kind,review_id) REFERENCES reviews(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE selections (change_id TEXT NOT NULL, slot TEXT NOT NULL CHECK(slot IN ('requirement-basis','design-basis','active-adoption','review-requirements','review-design','review-delivery','review-code')), kind TEXT NOT NULL, id TEXT NOT NULL, PRIMARY KEY(change_id,slot), FOREIGN KEY (change_id, kind, id) REFERENCES accounts(change_id, kind, id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE account_refs (change_id TEXT NOT NULL, owner_kind TEXT NOT NULL, owner_id TEXT NOT NULL, relation TEXT NOT NULL CHECK(relation IN ('review','prepared.basis_refs','assessment.evidence_refs','source_refs','review_refs','evidence_refs','check_refs')), ordinal INTEGER NOT NULL CHECK(ordinal>=0), target_kind TEXT NOT NULL, target_id TEXT NOT NULL, PRIMARY KEY(change_id,owner_kind,owner_id,relation,ordinal), FOREIGN KEY (change_id,owner_kind,owner_id) REFERENCES accounts(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (change_id,target_kind,target_id) REFERENCES accounts(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE subjects (change_id TEXT NOT NULL, owner_kind TEXT NOT NULL CHECK(owner_kind IN ('change','basis','review','evidence','decision','verification','adoption','work')), owner_id TEXT NOT NULL, account_id TEXT GENERATED ALWAYS AS (CASE WHEN owner_kind='change' THEN NULL ELSE owner_id END) STORED, role TEXT NOT NULL CHECK(role IN ('plan','subjects','prepared.subjects','prepared.plan','assessment.assessed_subjects','assessment.governing_basis','governing_basis')), ordinal INTEGER NOT NULL CHECK(ordinal>=0), path TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('present','absent')), identity TEXT, CHECK(state!='absent' OR identity IS NULL), CHECK(owner_kind!='change' OR owner_id=change_id), PRIMARY KEY(change_id,owner_kind,owner_id,role,ordinal), FOREIGN KEY (change_id) REFERENCES changes(change_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (change_id,owner_kind,account_id) REFERENCES accounts(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE work_blockers (change_id TEXT NOT NULL, work_kind TEXT NOT NULL DEFAULT 'work' CHECK(work_kind='work'), work_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), blocker_id TEXT NOT NULL, PRIMARY KEY(change_id,work_id,ordinal), FOREIGN KEY (change_id,work_kind,work_id) REFERENCES work(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (change_id,blocker_id) REFERENCES blockers(change_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE support_summaries (change_id TEXT NOT NULL, owner_kind TEXT NOT NULL CHECK(owner_kind IN ('review','verification')), owner_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), source_kind TEXT NOT NULL, source_id TEXT NOT NULL, scope TEXT NOT NULL, result TEXT NOT NULL, explanation TEXT NOT NULL, limitations TEXT NOT NULL CHECK(json_valid(limitations)), PRIMARY KEY(change_id,owner_kind,owner_id,ordinal), FOREIGN KEY (change_id,owner_kind,owner_id) REFERENCES accounts(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (change_id,source_kind,source_id) REFERENCES accounts(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE support_subjects (change_id TEXT NOT NULL, owner_kind TEXT NOT NULL, owner_id TEXT NOT NULL, support_ordinal INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), path TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('present','absent')), identity TEXT, CHECK(state!='absent' OR identity IS NULL), PRIMARY KEY(change_id,owner_kind,owner_id,support_ordinal,ordinal), FOREIGN KEY (change_id,owner_kind,owner_id,support_ordinal) REFERENCES support_summaries(change_id,owner_kind,owner_id,ordinal) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE attachments (change_id TEXT NOT NULL, name TEXT NOT NULL, media_type TEXT NOT NULL, byte_count INTEGER NOT NULL CHECK(byte_count>=0 AND byte_count<=67108864), PRIMARY KEY(change_id,name), FOREIGN KEY (change_id) REFERENCES changes(change_id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE completions (change_id TEXT PRIMARY KEY, actor TEXT NOT NULL CHECK(json_valid(actor)), verification_id TEXT NOT NULL, summary TEXT NOT NULL, reason TEXT NOT NULL, delivered_scope TEXT NOT NULL, governing_references TEXT NOT NULL CHECK(json_valid(governing_references)), acceptance TEXT NOT NULL CHECK(json_valid(acceptance)), limitations TEXT NOT NULL CHECK(json_valid(limitations)), FOREIGN KEY (change_id) REFERENCES changes(change_id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE completion_notes (change_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal>=0), actor TEXT NOT NULL CHECK(json_valid(actor)), reason TEXT NOT NULL, explanation TEXT NOT NULL, PRIMARY KEY(change_id,ordinal), FOREIGN KEY (change_id) REFERENCES changes(change_id) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE TABLE attachment_refs (change_id TEXT NOT NULL, owner_kind TEXT NOT NULL CHECK(owner_kind IN ('evidence','review','verification','completion')), owner_id TEXT NOT NULL, account_id TEXT GENERATED ALWAYS AS (CASE WHEN owner_kind='completion' THEN NULL ELSE owner_id END) STORED, completion_id TEXT GENERATED ALWAYS AS (CASE WHEN owner_kind='completion' THEN change_id ELSE NULL END) STORED, support_ordinal INTEGER, ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, CHECK((owner_kind IN ('review','verification') AND support_ordinal IS NOT NULL AND support_ordinal>=0) OR (owner_kind IN ('evidence','completion') AND support_ordinal IS NULL)), CHECK(owner_kind!='completion' OR owner_id=change_id), PRIMARY KEY(change_id,owner_kind,owner_id,ordinal), FOREIGN KEY (change_id,owner_kind,account_id) REFERENCES accounts(change_id,kind,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (completion_id) REFERENCES completions(change_id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (change_id,owner_kind,owner_id,support_ordinal) REFERENCES support_summaries(change_id,owner_kind,owner_id,ordinal) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY (change_id,name) REFERENCES attachments(change_id,name) DEFERRABLE INITIALLY DEFERRED) STRICT;
CREATE INDEX blockers_by_state ON blockers(change_id,state);
CREATE INDEX findings_by_state ON findings(change_id,state);
CREATE INDEX reviews_by_purpose ON reviews(change_id,purpose,applicability_value);
CREATE INDEX evidence_by_result ON evidence(change_id,result);
CREATE INDEX subjects_by_path ON subjects(path,owner_kind,owner_id);
CREATE INDEX account_ref_targets ON account_refs(change_id,target_kind,target_id);
CREATE INDEX attachment_ref_targets ON attachment_refs(change_id,name);
PRAGMA user_version=1;
